WITH micro AS (SELECT * FROM UNNEST(['PA-1506187-94551B72659E427F961D2F62CEBA7392','PA-1506187-CEAD1A3AC3E14F5DB2FC0B93E54E7E98','MS-5006606-4693892971CF47B4B2684C3A94950BEE','BA-2921401-9177991E4861442EACDDC06DB91','BA-2929057-C5D11EE026A64399A6EF36764E8739E9']) AS id_car),viz AS (SELECT * FROM UNNEST(['PA-1506187-878F5B604D8E471F8DE7F692F7F7288C','PA-1506187-3F4B7241FA0D4F60B91CCE115953FD56','PA-1506187-48EDE9CDCF3947959921871671228876','MS-5006606-9F4376C099A342D2899444A8DB7FADE6','MS-5006606-F52D5261C8504529A0FC680C01132DA2','BA-2921401-0F05B7015F404007905C0A598A258AF4','BA-2929057-43362B5DD011494FA6B0EE05C2761D93']) AS id_car),ids AS (SELECT id_car FROM micro UNION DISTINCT SELECT id_car FROM viz),p AS (SELECT DISTINCT id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao=2023),x AS (SELECT CASE WHEN p.id_car_norm IN (SELECT REPLACE(id_car,'-','') FROM micro) THEN 'micro_alvo' ELSE 'vizinho' END grupo,p.id_car_norm,p.id_referencia_bacen,p.numero_ordem,op.valor_parcela_credito,op.area_financiada FROM p JOIN `basedosdados.br_bcb_sicor.operacao` op USING(id_referencia_bacen,numero_ordem) WHERE p.id_car_norm IN (SELECT REPLACE(id_car,'-','') FROM ids) AND op.ano_emissao=2023) SELECT grupo,id_car_norm,COUNT(DISTINCT id_referencia_bacen) operacoes,COUNT(*) linhas,SUM(valor_parcela_credito) credito_na_base,SUM(area_financiada) area_financiada FROM x GROUP BY grupo,id_car_norm ORDER BY grupo,id_car_norm